"use client";

import { LifeSimulation } from "./LifeSimulation";

export default function BuggedOutGameOfLifeShaderExperiment() {
  return (
    <div className="relative h-full min-h-[400px] w-full">
      <LifeSimulation />
    </div>
  );
}

"use client";

import type React from "react";
import { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { GradientBackground } from "./GradientBackground";

interface LifeSimulationProps {
  className?: string;
}

const CELL_SIZE = 8;

/**
 * LifeSimulation Component
 *
 * Logic Refinement:
 * 1. Boosted reactivity to sparse populations.
 * 2. Increased STABLE_AGE to make patterns more distinct.
 */
export function LifeSimulation({ className }: LifeSimulationProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const gradientContainerRef = useRef<HTMLDivElement>(null);
  const workerRef = useRef<Worker>(null);

  const [resolution, setResolution] = useState({ w: 0, h: 0 });

  // Reactive Shader Stats
  const [stats, setStats] = useState({
    density: 0,
    activity: 0,
    centroidX: 0.5,
    centroidY: 0.5,
  });

  /**
   * WORKER INITIALIZATION
   */
  useEffect(() => {
    workerRef.current = new Worker(
      new URL("./simulation.worker.ts", import.meta.url)
    );

    const handleResize = () => {
      if (!containerRef.current) {
        return;
      }
      const { clientWidth, clientHeight } = containerRef.current;

      const w = Math.ceil(clientWidth / CELL_SIZE);
      const h = Math.ceil(clientHeight / CELL_SIZE);

      setResolution({ w, h });

      workerRef.current?.postMessage({
        type: "INIT",
        width: w,
        height: h,
      });
    };

    window.addEventListener("resize", handleResize);
    handleResize();

    return () => {
      window.removeEventListener("resize", handleResize);
      workerRef.current?.terminate();
    };
  }, []);

  /**
   * RENDER LOOP
   */
  useEffect(() => {
    if (!(canvasRef.current && workerRef.current) || resolution.w === 0) {
      return;
    }

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d", { alpha: true });
    if (!ctx) {
      return;
    }

    canvas.width = resolution.w;
    canvas.height = resolution.h;
    ctx.imageSmoothingEnabled = false;

    const volatileCanvas = document.createElement("canvas");
    volatileCanvas.width = resolution.w;
    volatileCanvas.height = resolution.h;
    const volatileCtx = volatileCanvas.getContext("2d");

    const stableCanvas = document.createElement("canvas");
    stableCanvas.width = resolution.w;
    stableCanvas.height = resolution.h;
    const stableCtx = stableCanvas.getContext("2d");

    if (!(volatileCtx && stableCtx)) {
      return;
    }

    let animateId: number;
    let lastGrid: Uint8Array | null = null;
    let lastAgeGrid: Uint8Array | null = null;

    workerRef.current.onmessage = (e) => {
      if (e.data.type === "UPDATE") {
        lastGrid = e.data.grid;
        lastAgeGrid = e.data.ageGrid;

        // Reactive stats with smoothing
        setStats((prev) => ({
          density: prev.density * 0.95 + e.data.stats.density * 0.05,
          activity: prev.activity * 0.9 + e.data.stats.activity * 0.1,
          centroidX:
            prev.centroidX * 0.98 + (e.data.stats.centroidX - 0.5) * 0.02,
          centroidY:
            prev.centroidY * 0.98 + (e.data.stats.centroidY - 0.5) * 0.02,
        }));
      }
    };

    const render = () => {
      workerRef.current?.postMessage({ type: "TICK" });

      if (lastGrid && lastAgeGrid && ctx) {
        ctx.clearRect(0, 0, resolution.w, resolution.h);
        volatileCtx.clearRect(0, 0, resolution.w, resolution.h);
        stableCtx.clearRect(0, 0, resolution.w, resolution.h);

        const vData = volatileCtx.createImageData(resolution.w, resolution.h);
        const sData = stableCtx.createImageData(resolution.w, resolution.h);
        const vPixels = vData.data;
        const sPixels = sData.data;

        // Threshold for "Stable" behavior (slightly increased for better visual logic)
        const STABLE_AGE = 20;

        for (let i = 0; i < lastGrid.length; i++) {
          const stride = i * 4;
          const val = lastGrid[i];
          const age = lastAgeGrid[i];

          if (val > 0) {
            if (val === 255) {
              if (age < STABLE_AGE) {
                vPixels[stride] = 255;
                vPixels[stride + 1] = 255;
                vPixels[stride + 2] = 255;
                vPixels[stride + 3] = 255;
              } else {
                sPixels[stride] = 255;
                sPixels[stride + 1] = 255;
                sPixels[stride + 2] = 255;
                sPixels[stride + 3] = 255;
              }
            } else {
              vPixels[stride] = 255;
              vPixels[stride + 1] = 255;
              vPixels[stride + 2] = 255;
              vPixels[stride + 3] = val;
            }
          }
        }

        volatileCtx.putImageData(vData, 0, 0);
        stableCtx.putImageData(sData, 0, 0);

        const sourceCanvas =
          gradientContainerRef.current?.querySelector("canvas");
        if (sourceCanvas) {
          ctx.globalCompositeOperation = "source-over";
          ctx.drawImage(volatileCanvas, 0, 0);
          ctx.globalCompositeOperation = "source-in";
          ctx.drawImage(sourceCanvas, 0, 0, resolution.w, resolution.h);

          stableCtx.globalCompositeOperation = "source-in";
          stableCtx.filter = "hue-rotate(90deg) brightness(1.2)";
          stableCtx.drawImage(sourceCanvas, 0, 0, resolution.w, resolution.h);
          stableCtx.filter = "none";

          ctx.globalCompositeOperation = "screen";
          ctx.drawImage(stableCanvas, 0, 0);
        }
      }

      animateId = requestAnimationFrame(render);
    };

    render();

    return () => {
      cancelAnimationFrame(animateId);
    };
  }, [resolution]);

  // Input handlers
  const handlePointerMove = (e: React.PointerEvent) => {
    if (!(containerRef.current && workerRef.current)) {
      return;
    }
    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / CELL_SIZE);
    const y = Math.floor((e.clientY - rect.top) / CELL_SIZE);

    workerRef.current.postMessage({ type: "SPLAT", x, y, radius: 4 });
  };

  const handlePointerDown = () => {
    workerRef.current?.postMessage({ type: "RESET" });
  };

  // REFINED MAPPING
  // Use a higher base intensity so it's NEVER dark
  const derivedIntensity = 0.3 + Math.min(0.6, stats.density * 20);
  // Speed increases more aggressively with activity
  const derivedSpeed = 0.5 + Math.min(2.5, stats.activity * 25);
  // Noise only appears during high turnovers
  const derivedNoise = Math.min(0.5, stats.activity * 10);

  return (
    <div
      className={cn("absolute inset-0 z-0", className)}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      ref={containerRef}
      style={{ touchAction: "none", pointerEvents: "auto" }}
    >
      <canvas
        className="rendering-pixelated block h-full w-full"
        ref={canvasRef}
        style={{ imageRendering: "pixelated" }}
      />

      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 opacity-0"
        ref={gradientContainerRef}
      >
        <GradientBackground
          intensity={derivedIntensity}
          noise={derivedNoise}
          offsetX={stats.centroidX * 30}
          offsetY={stats.centroidY * 30}
          speed={derivedSpeed}
        />
      </div>
    </div>
  );
}

"use client";

import { GrainGradient } from "@paper-design/shaders-react";

interface GradientBackgroundProps {
  intensity?: number;
  noise?: number;
  offsetX?: number;
  offsetY?: number;
  softness?: number;
  speed?: number;
}

/**
 * GradientBackground Component
 *
 * FIX: 'colorBack' set to Primary Orange to eliminate the "Black Hole".
 * FIX: 'shape' set to "wave" for better screen coverage.
 */
export function GradientBackground({
  intensity = 0.45,
  speed = 1,
  noise = 0,
  softness = 0.76,
  offsetX = 0,
  offsetY = 0,
}: GradientBackgroundProps) {
  return (
    <div className="absolute inset-0 -z-10">
      <GrainGradient
        colorBack="hsl(14, 100%, 57%)"
        // Use the primary orange as background so cells in the "center" are always visible
        colors={[
          "hsl(14, 100%, 57%)",
          "hsl(45, 100%, 51%)",
          "hsl(340, 82%, 52%)",
        ]}
        intensity={intensity}
        noise={noise}
        offsetX={offsetX}
        offsetY={offsetY} // Wave provides better overall texture than blob or corners
        rotation={0}
        scale={1.4}
        shape="wave" // Increase scale to ensure full coverage
        softness={softness}
        speed={speed}
        style={{ height: "100%", width: "100%" }}
      />
    </div>
  );
}

export {};

/**
 * SIMULATION WORKER
 * -----------------
 * This Web Worker handles the mathematical core of the Game of Life.
 */

// Message Types for Type Safety
type WorkerMessage =
  | { type: "INIT"; width: number; height: number }
  | { type: "TICK" }
  | { type: "SPLAT"; x: number; y: number; radius: number }
  | { type: "RESET" };

// Cell States
const ALIVE = 255;
const DEAD = 0;

// Age Parameters
const MAX_AGE = 255;

/**
 * DECAY_RATE determines the length of the "Ghost Trails".
 * Slightly increased for smoother visual transitions.
 */
const DECAY_RATE = 4;

// Internal State
let grid: Uint8Array;
let nextGrid: Uint8Array;
let ageGrid: Uint8Array;
let nextAgeGrid: Uint8Array;

let width = 0;
let height = 0;

/**
 * Initialize the grid memory buffers.
 */
function initGrid(w: number, h: number) {
  width = w;
  height = h;
  const size = width * height;

  grid = new Uint8Array(size);
  nextGrid = new Uint8Array(size);
  ageGrid = new Uint8Array(size);
  nextAgeGrid = new Uint8Array(size);

  randomize();
}

/**
 * Seed the universe with random chaos.
 */
function randomize() {
  for (let i = 0; i < grid.length; i++) {
    const isAlive = Math.random() > 0.85;
    grid[i] = isAlive ? ALIVE : DEAD;
    ageGrid[i] = 0;
  }
}

/**
 * THE MAIN SIMULATION LOOP (TICK)
 *
 * Logic Repair: Neighbor counting now considers "mostly alive" cells (> 128)
 * as neighbors. This makes the simulation much more robust to decaying trails.
 */
function tick() {
  if (!(grid && width)) {
    return;
  }

  const wReal = width;
  const hReal = height;

  // Stats calculation
  let totalAlive = 0;
  let totalBirths = 0;
  let sumX = 0;
  let sumY = 0;

  for (let y = 0; y < hReal; y++) {
    const yUp = ((y - 1 + hReal) % hReal) * wReal;
    const ySame = y * wReal;
    const yDown = ((y + 1) % hReal) * wReal;

    for (let x = 0; x < wReal; x++) {
      const xLeft = (x - 1 + wReal) % wReal;
      const xRight = (x + 1) % wReal;

      // Neighbor counting with fuzzy logic (counting trails)
      let neighbors = 0;
      if (grid[yUp + xLeft] > 128) {
        neighbors++;
      }
      if (grid[yUp + x] > 128) {
        neighbors++;
      }
      if (grid[yUp + xRight] > 128) {
        neighbors++;
      }
      if (grid[ySame + xLeft] > 128) {
        neighbors++;
      }
      if (grid[ySame + xRight] > 128) {
        neighbors++;
      }
      if (grid[yDown + xLeft] > 128) {
        neighbors++;
      }
      if (grid[yDown + x] > 128) {
        neighbors++;
      }
      if (grid[yDown + xRight] > 128) {
        neighbors++;
      }

      const selfIndex = ySame + x;
      const selfVal = grid[selfIndex];
      const selfAge = ageGrid[selfIndex];

      // CONWAY RULES
      if (selfVal === ALIVE) {
        if (neighbors === 2 || neighbors === 3) {
          nextGrid[selfIndex] = ALIVE;
          nextAgeGrid[selfIndex] = Math.min(MAX_AGE, selfAge + 1);
        } else {
          nextGrid[selfIndex] = Math.max(0, selfVal - DECAY_RATE);
          nextAgeGrid[selfIndex] = 0;
        }
      } else if (neighbors === 3) {
        nextGrid[selfIndex] = ALIVE;
        nextAgeGrid[selfIndex] = 0;
      } else {
        nextGrid[selfIndex] = Math.max(0, selfVal - DECAY_RATE);
        nextAgeGrid[selfIndex] = 0;
      }

      // Stats update
      if (nextGrid[selfIndex] === ALIVE) {
        totalAlive++;
        sumX += x;
        sumY += y;
        if (nextAgeGrid[selfIndex] === 0) {
          totalBirths++;
        }
      }
    }
  }

  const totalCells = wReal * hReal;
  const stats = {
    density: totalAlive / totalCells,
    activity: totalBirths / Math.max(1, totalAlive),
    centroidX: totalAlive > 0 ? sumX / totalAlive / wReal : 0.5,
    centroidY: totalAlive > 0 ? sumY / totalAlive / hReal : 0.5,
  };

  const tempGrid = grid;
  grid = nextGrid;
  nextGrid = tempGrid;

  const tempAge = ageGrid;
  ageGrid = nextAgeGrid;
  nextAgeGrid = tempAge;

  self.postMessage({ type: "UPDATE", grid, ageGrid, stats });
}

function splat(centerX: number, centerY: number, radius: number) {
  if (!grid) {
    return;
  }
  const r2 = radius * radius;
  for (let y = -radius; y <= radius; y++) {
    for (let x = -radius; x <= radius; x++) {
      if (x * x + y * y <= r2) {
        const tX = (centerX + x + width) % width;
        const tY = (centerY + y + height) % height;
        if (Math.random() > 0.5) {
          const idx = tY * width + tX;
          grid[idx] = ALIVE;
          ageGrid[idx] = 0;
        }
      }
    }
  }
}

self.onmessage = (e: MessageEvent<WorkerMessage>) => {
  const { type } = e.data;
  switch (type) {
    case "INIT":
      initGrid(e.data.width, e.data.height);
      break;
    case "TICK":
      tick();
      break;
    case "SPLAT":
      splat(e.data.x, e.data.y, e.data.radius);
      break;
    case "RESET":
      randomize();
      break;
  }
};
